   277→        sidecars.push(
   278→            DataColumnSidecar {
   279→                index: ColumnIndex::try_from(column_index)?,
   280→                column,
   281→                kzg_commitments: kzg_commitments.clone(),
   282→                kzg_proofs,
   283→                signed_block_header,
   284→                kzg_commitments_inclusion_proof,
   285→            }
   286→            .into(),
   287→        );
   288→    }
   289→
   290→    Ok(sidecars)
   291→}
