                    ValidatorToP2p::PublishDataColumnSidecar(data_column_sidecar)
                        .send(&self.p2p_tx);
                }
            }
        } else {
            for blob_sidecar in misc::construct_blob_sidecars(
                &block,
                blobs.into_iter(),
