                    .into_iter(),
            )? {
                let blob_sidecar = Arc::new(blob_sidecar);

                self.controller.on_own_blob_sidecar(
                    wait_group.clone(),
                    blob_sidecar.clone_arc(),
                );

                ValidatorToP2p::PublishBlobSidecar(blob_sidecar).send(&self.p2p_tx);
